/* ---------- Rewrite toolbar ---------- */
/* a document whose sentences you click; a small toolbar over the one you pick offers rewrites, and the new sentence is
   written in after the old one, struck, a word at a time, to accept or undo. No room is kept for the words to come (owner,
   18 Nov): the text grows as they arrive (grow()), the card with it, and the toolbar glides along under the last line */
.rwx{padding:var(--dm-s-4);position:relative}
/* (the kind, the title and the status are all words, so the row lines them up by their baseline) */
.rwx-h{display:flex;align-items:baseline;gap:var(--dm-s-2);font-size:13px;font-weight:500;margin-bottom:10px}
.rwx-st{margin-left:auto;font-weight:400;font-size:12px}
.rwx-doc{font-size:14px;line-height:24px;color:var(--dm-fg2)}
/* grow() wraps the text: it stays one flowing paragraph */
.rwx-doc>.dm-grow{display:block}
.rwx-s{border-radius:var(--dm-r-tiny,5px);cursor:text;transition:background .3s,color .3s;padding:1px 0;box-decoration-break:clone;-webkit-box-decoration-break:clone}
@media (hover:hover) and (pointer:fine){.rwx-s:hover{background:var(--dm-row);color:var(--dm-fg)}}
.rwx-s.sel{background:var(--dm-sel);color:var(--dm-fg)}
/* once it holds a rewrite, the struck words and the new ones say which sentence it is: the tint goes, so the words still
   fading in never show as an empty tinted band ahead of the text */
.rwx-s.sel:has(ins){background:none}
.rwx-s.sel del{color:var(--dm-fg2)}
/* the words it replaces keep the text grey and are struck with the bright red mark; the new ones are in the text colour */
.rwx-s del{color:var(--dm-muted);text-decoration-color:var(--dm-bad-mark)}
.rwx-s ins{text-decoration:none;color:var(--dm-fg)}
.rwx-s ins .w{animation:rww .4s var(--dm-ease) both}
@keyframes rww{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.rwx-tb{position:absolute;left:0;top:0;display:flex;align-items:center;gap:2px;padding:var(--dm-s-1);border-radius:var(--dm-r-pill);background:var(--dm-ink);color:var(--dm-on-ink);box-shadow:var(--dm-shadow-pop);opacity:0;pointer-events:none;transform:translateY(6px) scale(.96);filter:blur(4px);transition:opacity .3s var(--dm-ease),transform .4s var(--dm-ease),filter .3s,top var(--dm-t) var(--dm-ease),left var(--dm-t) var(--dm-ease);z-index:3;white-space:nowrap}
.rwx-tb.show{opacity:1;pointer-events:auto;transform:none;filter:none}
/* "Rewriting" shimmers while the agent writes, in the toolbar's own ink; done, the tick is the vivid mark green */
.rwx-tb .shim{background-image:linear-gradient(90deg,var(--dm-on-ink) 0%,var(--dm-on-ink) 38%,color-mix(in srgb,var(--dm-on-ink) 35%,var(--dm-ink)) 50%,var(--dm-on-ink) 62%,var(--dm-on-ink) 100%)}
.rwx-tb .lbl>svg{color:var(--dm-ok-mark)}
.rwx-b{display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 11px;border-radius:var(--dm-r-pill);font-size:12.5px;color:inherit;opacity:.85;transition:background .2s,opacity .2s}
.rwx-b.hl{background:color-mix(in srgb,var(--dm-on-ink) 14%,transparent);opacity:1}
@media (hover:hover) and (pointer:fine){.rwx-b:hover{background:color-mix(in srgb,var(--dm-on-ink) 14%,transparent);opacity:1}}
.rwx-b.ic{width:28px;padding:0;justify-content:center}
.rwx-sep{width:1px;height:16px;background:color-mix(in srgb,var(--dm-on-ink) 25%,transparent);margin:0 2px}
.rwx-tb.act{padding:var(--dm-s-1) var(--dm-s-1) var(--dm-s-1) var(--dm-s-3)}
.rwx-tb .lbl{font-size:12.5px;margin-right:6px;display:flex;align-items:center;gap:7px}
.rwx-tb .pill.sm{height:28px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's primary alone presses */
.rwx .pill:active{transform:none}
/* in dark mode the toolbar is the raised dark surface with a hairline, not the inverted light ink (owner, 10 Nov) */
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .rwx-tb{--dm-ink:var(--dm-raised);--dm-on-ink:var(--dm-fg);box-shadow:var(--dm-shadow-pop),inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 12%,transparent)}}
:root[data-theme="dark"] .rwx-tb{--dm-ink:var(--dm-raised);--dm-on-ink:var(--dm-fg);box-shadow:var(--dm-shadow-pop),inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 12%,transparent)}
@media (prefers-reduced-motion:reduce){.rwx-tb .shim{color:var(--dm-on-ink);background:none}}
/* Clean (owner, 19 Nov): its content 16px from every edge; the file's mark is the neutral grey every Clean file mark is.
   The toolbar is the ink pill (black in light, the raised grey in dark) and opens from the sentence by scaling and fading,
   with no blur; its Accept is the white button, so it stands out on the ink (the dark mode's white button, with its faint
   glow only in dark). Words fade in without a blur */
:root[data-style="clean"] .rwx.panel,:root [data-style="clean"] .rwx.panel,:root [data-style="clean"].rwx.panel{padding:16px}
:root[data-style="clean"] .rwx-h .ft,:root [data-style="clean"] .rwx-h .ft,:root [data-style="clean"].rwx-h .ft{color:var(--dm-muted)}
:root[data-style="clean"] .rwx-tb,:root [data-style="clean"] .rwx-tb,:root [data-style="clean"].rwx-tb{filter:none;transform:translateY(4px) scale(.96);transform-origin:top left;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),top var(--dm-t) var(--dm-ease),left var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .rwx-tb.show,:root [data-style="clean"] .rwx-tb.show,:root [data-style="clean"].rwx-tb.show{transform:none}
:root[data-style="clean"] .rwx-b,:root [data-style="clean"] .rwx-b,:root [data-style="clean"].rwx-b{transition:background-color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .rwx-s,:root [data-style="clean"] .rwx-s,:root [data-style="clean"].rwx-s{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .rwx-s ins .w,:root [data-style="clean"] .rwx-s ins .w,:root [data-style="clean"].rwx-s ins .w{animation:rwwc var(--dm-t-fast) var(--dm-ease) both}
@keyframes rwwc{from{opacity:0}}
:root[data-style="clean"] .rwx-tb,:root [data-style="clean"] .rwx-tb,:root [data-style="clean"].rwx-tb{--dm-btn-1:#ffffff;--dm-btn-2:#e0e0e0;--dm-on-btn:#0a0a0a;--dm-btn-depth:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 3px 5px -2px #ffffff,inset 0 -3px 5px -3px rgba(0,0,0,.18),0 1px 2px rgba(0,0,0,.5);--dm-btn-press:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 1px 3px rgba(0,0,0,.3),inset 0 -3px 5px -3px rgba(0,0,0,.2),0 1px 1px rgba(0,0,0,.4)}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .rwx-tb,:root:not([data-theme="light"]) [data-style="clean"] .rwx-tb,:root:not([data-theme="light"]) [data-style="clean"].rwx-tb{--dm-btn-depth:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 3px 5px -2px #ffffff,inset 0 -3px 5px -3px rgba(0,0,0,.18),0 1px 2px rgba(0,0,0,.5),0 0 14px rgba(255,255,255,.16)}}
:root[data-style="clean"][data-theme="dark"] .rwx-tb,:root[data-theme="dark"] [data-style="clean"] .rwx-tb,:root[data-theme="dark"] [data-style="clean"].rwx-tb{--dm-btn-depth:inset 0 0 0 1px rgba(245,245,245,.9),inset 0 3px 5px -2px #ffffff,inset 0 -3px 5px -3px rgba(0,0,0,.18),0 1px 2px rgba(0,0,0,.5),0 0 14px rgba(255,255,255,.16)}

DM.def('rewrite-toolbar', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{spark}', I('spark','xs')).replace('{at}', I('wand','xs'));
  const S = [
    ['Welcome to DesignMe, a place where you and your team can work together with an agent on all of your design files in one place.', { clear:'DesignMe is where your team and an agent design together.', short:'Design with your team and an agent.', warm:'Welcome in. This is where you, your team and your agent make things together.' }],
    ['To get started you will need to connect Figma, which can be done from the settings page at any time.', { clear:'Connect Figma in Settings to get started.', short:'First, connect Figma.', warm:'Start by connecting Figma. It takes about a minute.' }],
    ['After that, the agent will be able to read your frames and suggest improvements.', { clear:'Then the agent can read your frames and suggest fixes.', short:'Then the agent reviews your frames.', warm:'Then your agent can look through your frames and help polish them.' }]
  ];
  const doc = $('.rwx-doc', r), tb = $('.rwx-tb', r), st = $('.rwx-st', r), box = $('.rwx', r);
  doc.innerHTML = S.map((s, i) => `<span class="rwx-s" data-i="${i}">${s[0]}</span>`).join(' ');
  const tbHTML = tb.innerHTML; let sel = null, busy = false;
  // no room is kept for a rewrite (owner, 18 Nov): the text grows as its words arrive and shrinks once one is kept, and the
  // card eases with it (grow()), staying centred in its stage. Only the text clips while it eases, so the toolbar never does
  c.offs.push(grow(doc));
  // the box is the card's layout box, so a card still scaling in from its entrance places the toolbar where it will be
  function place(el){
    const br = box.getBoundingClientRect(), k = br.width / box.offsetWidth || 1, rects = el.getClientRects(), f = rects[0];
    if (!f) return; // the card is hidden (far off screen, or the other set is showing): nothing to place against
    const w = tb.offsetWidth; let x = (f.left - br.left) / k; x = Math.max(8, Math.min(x, box.offsetWidth - w - 8));
    // above the sentence, unless that would cover the header: then under its last line, gliding down with it as the new
    // words add lines. A toolbar that isn't showing yet jumps to its place
    let y = (f.top - br.top) / k - tb.offsetHeight - 8; if (y < ($('.rwx-h', r).getBoundingClientRect().bottom - br.top) / k) y = (rects[rects.length - 1].bottom - br.top) / k + 8;
    const jump = !tb.classList.contains('show');
    if (jump) tb.style.transitionProperty = 'opacity,transform,filter';
    tb.style.left = x + 'px'; tb.style.top = y + 'px';
    if (jump){ void tb.offsetWidth; tb.style.transitionProperty = ''; }
  }
  // hidden, the toolbar takes no focus
  function hide(){ tb.classList.remove('show'); tb.inert = true; }
  tb.inert = true;
  function bindTb(){ $$('.rwx-b[data-k]', tb).forEach(b => b.onclick = () => rewrite(b.dataset.k)); const a = $('.rwx-b.ic', tb); if (a) a.onclick = () => rewrite('clear'); }
  function select(el){
    if (busy) return; $$('.rwx-s', doc).forEach(x => x.classList.toggle('sel', x === el)); sel = el;
    tb.classList.remove('act'); tb.innerHTML = tbHTML; bindTb(); place(el); tb.inert = false; tb.classList.add('show'); swap(st, 'Pick a rewrite');
  }
  $$('.rwx-s', doc).forEach(el => el.onclick = e => { e.stopPropagation(); if (!el.querySelector('ins')) select(el); });
  c.on(document, 'pointerdown', e => { if (!busy && !r.contains(e.target)) { hide(); $$('.rwx-s', doc).forEach(x => x.classList.remove('sel')); } });
  function rewrite(k){
    const el = sel, i = +el.dataset.i, old = S[i][0], nw = S[i][1][k]; busy = true;
    tb.classList.add('act'); tb.innerHTML = `<span class="lbl"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Rewriting</span></span>`; place(el);
    c.run(async () => {
      // the new words arrive one at a time after the struck sentence, each only once it is written
      el.innerHTML = `<del>${old}</del> <ins></ins>`; const ins = $('ins', el); place(el); await c.wait(350);
      for (const w of nw.split(' ')){ const s = document.createElement('span'); s.className = 'w'; s.textContent = w + ' '; ins.appendChild(s); place(el); await c.wait(55); }
      tb.innerHTML = `<span class="lbl">${I('check','xs')}Rewritten</span><button class="rwx-b rwx-un">Undo</button><button class="pill accent sm rwx-ok">Accept</button>`; place(el);
      // keeping a shorter sentence lets the doc fit its text, with no empty room above or below it
      $('.rwx-ok', tb).onclick = () => { el.textContent = nw; S[i][0] = nw; el.classList.remove('sel'); hide(); busy = false; swap(st, 'Saved'); };
      $('.rwx-un', tb).onclick = () => { el.textContent = old; el.classList.remove('sel'); hide(); busy = false; swap(st, 'Click a sentence'); };
    });
  }
  bindTb();
  // the preview plays it once on its own after the entrance: pick a sentence, make it clearer, keep it. A click of yours takes over
  c.run(async () => {
    await c.step(1300); if (sel) return; select($$('.rwx-s', doc)[0]);
    await c.step(1200); const b = $('.rwx-b[data-k="clear"]', tb); if (busy || !b) return;
    b.classList.add('hl'); c.taken(() => b.classList.remove('hl')); await c.step(240); b.classList.remove('hl'); rewrite('clear');
    await c.step(2600); const ok = $('.rwx-ok', tb); if (!ok) return;
    ok.classList.add('hl'); c.taken(() => ok.classList.remove('hl')); await c.step(240); ok.click();
  });
});
